CREATE OR REPLACE FUNCTION public.prevent_disabled_first_session_promo() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='profiles' THEN IF NEW.first_session_promo_sent IS DISTINCT FROM OLD.first_session_promo_sent AND NEW.first_session_promo_sent IS NOT NULL THEN RAISE EXCEPTION 'First Session Free promotion is disabled'; END IF; ELSE IF NEW.transaction_type='promo_credit' AND NEW.description LIKE 'First Session Free%' AND NEW.amount>0 THEN RAISE EXCEPTION 'First Session Free promotion is disabled'; END IF; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.prevent_disabled_first_session_promo() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER prevent_disabled_first_session_profile BEFORE UPDATE OF first_session_promo_sent ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.prevent_disabled_first_session_promo();
CREATE TRIGGER prevent_disabled_first_session_credit BEFORE INSERT ON public.deposit_transactions FOR EACH ROW EXECUTE FUNCTION public.prevent_disabled_first_session_promo();